// 方法
const loadSettings = () => {
  try {
    const savedSettings = localStorage.getItem('homepage_settings')
    if (savedSettings) {
      const settings = JSON.parse(savedSettings)
      if (settings.backgroundImage) {
        currentBackground.value = settings.backgroundImage
      }
      if (settings.heroContent) {
        heroContent.value = { ...heroContent.value, ...settings.heroContent }
      }
      if (settings.partners) {
        partners.value = settings.partners
      }
    }
  } catch (error) {
    console.error('Failed to load settings:', error)
  }
}

const saveSettings = () => {
  try {
    const settings = {
      backgroundImage: currentBackground.value,
      heroContent: heroContent.value,
      partners: partners.value
    }
    localStorage.setItem('homepage_settings', JSON.stringify(settings))
  } catch (error) {
    console.error('Failed to save settings:', error)
  }
}

const selectPreset = (preset: any) => {
  currentBackground.value = preset.url
  saveSettings()
  showMessage.value = true
  message.value = `已设置为: ${preset.name}`
  messageType.value = 'success'
}

const handleFileUpload = (files: File | File[]) => {
  const fileArray = Array.isArray(files) ? files : [files]
  if (fileArray && fileArray.length > 0) {
    const file = fileArray[0]
    if (file.type.startsWith('image/')) {
      const reader = new FileReader()
      reader.onload = (e) => {
        currentBackground.value = e.target?.result as string
        saveSettings()
        showMessage.value = true
        message.value = '背景图片已上传'
        messageType.value = 'success'
      }
      reader.readAsDataURL(file)
    } else {
      showMessage.value = true
      message.value = '请选择图片文件'
      messageType.value = 'error'
    }
  }
}

const previewBackground = () => {
